#!/usr/bin/env bash
# U6 audit, subjective lane: Astra (analyst) through codex exec read-only rooted at the Test
# checkout. Astra wrote U6, so it holds the subjective lane and native Opus (reviewer) holds
# the objective lane. Journal: scaffold/tmp/codex/u6-audit-analyst.jsonl.
cd "C:/Users/mikes/WebstormProjects/test" || exit 9
timeout 3000 codex exec --json -C "C:/Users/mikes/WebstormProjects/test" --sandbox read-only --model gpt-6-astra -c 'model_reasoning_effort="high"' --output-last-message "units/u6-audit-analyst-last.md" "You hold the SUBJECTIVE lane (shape, naming, ergonomics, guide voice, design fit) of an audit of the unit your own engine wrote; judge it as a stranger would. Read ./tmp/audit/u6-audit-claims.md and rule on every claim 1 to 13 with CONFIRMED, REFUTED, or UNDECIDABLE and the deciding evidence (file:line or exact text), reading the working tree of this checkout (HEAD f49bc7f plus the uncommitted U6 diff), the diff at ./tmp/audit/u6-diff.patch, the reports at ./tmp/codex/u6-report.md and ./tmp/codex/u6-report-2.md, the design at C:/Users/mikes/WebstormProjects/scaffold/.orkestrel/veneer/units/u6-design-planner-report.md and C:/Users/mikes/WebstormProjects/scaffold/.orkestrel/veneer/u6-design-verdict.md, and the rules under C:/Users/mikes/WebstormProjects/scaffold/AGENTS.md and .claude/rules/. Run no command that writes. Add extra findings no claim names, numbered from 14, with sites. End with one terminal line: Verdict: accept, or Verdict: fix round with the claims that force it." < /dev/null > "units/u6-audit-analyst.jsonl" 2> "units/u6-audit-analyst.err"
echo "exit=$?" >> "units/u6-audit-analyst.err"
